def canPartitionKSubsets(nums, k):
    total = sum(nums)
    if total % k != 0: return False
    target = total // k
    n = len(nums)
    dp = [-1] * (1 << n)
    dp[0] = 0

    for mask in range(1 << n):
        if dp[mask] == -1: continue
        for i in range(n):
            if not (mask & (1 << i)):
                if dp[mask] + nums[i] <= target:
                    next_mask = mask | (1 << i)
                    dp[next_mask] = (dp[mask] + nums[i]) % target
    return dp[(1 << n) - 1] == 0

