from collections import defaultdict, deque

def longest_path_dag(n, edges):
    adj = defaultdict(list)
    in_degree = [0] * n
    for u, v, w in edges:
        adj[u].append((v, w))
        in_degree[v] += 1

    queue = deque([i for i in range(n) if in_degree[i] == 0])
    dp = [0] * n  # dp[u] = max distance to node u

    while queue:
        u = queue.popleft()
        for v, w in adj[u]:
            dp[v] = max(dp[v], dp[u] + w)
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)
    return max(dp)

